# Astra sixteen-state potential probe -- owned paths only /tmp/astra_sixteen_potential.py,json
# Hypothesis: fixed real additive edge weights omega(r,g) on 16-state scanner graph,
# bounded below over ALL ordinary histories from both phase roots, strictly decrease
# across EVERY genuine 3-return block with prescribed H+Q update.
# Scope: ONLY six already-certified named blocks, no new words/frontiers/occurrences.
# Method: exact integer arithmetic, coeff cube 0..4 bounded 5^6=15625, no SciPy, local only.
# Caps: CPU 120s, wall 180s, 1GiB. Preregistered before experiment.
import hashlib, json, os, sys, time, platform, itertools, subprocess
START_WALL = time.time()
START_CPU = time.process_time()
CPU_CAP = 120.0
WALL_CAP = 180.0
def check_caps():
    wc = time.time() - START_WALL
    cc = time.process_time() - START_CPU
    if cc > CPU_CAP or wc > WALL_CAP:
        raise RuntimeError('resource cap exceeded')
    try:
        import resource
        mem = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
        # ru_maxrss in KB on Linux
        if mem > 1048576:
            raise RuntimeError('memory cap exceeded')
    except ImportError:
        pass
def T(x):
    return x ^ ((x << 1) | (x << 2))
def U(x):
    return T(x) ^ 1
def P(x):
    return T((2 * x) + 1) >> 1
def A(x):
    return T(x) >> 2
def PIX(x):
    return x >> 2
S_of = {0: 't', 1: 'u', 2: 'p', 3: 'p'}
GENS = {'t': T, 'u': U, 'p': P}
GI = {'t': 0, 'u': 1, 'p': 2}
ROOTS = {'p': 3, 'u': 1}
def eval_word(root, w):
    z = root
    prefs = [root]
    for ch in w:
        z = GENS[ch](z)
        prefs.append(z)
    return z, prefs
def scanner_H(root, w):
    z, prefs = eval_word(root, w)
    out = []
    for i in range(1, len(prefs)):
        out.append(S_of[prefs[i] % 4])
    return ''.join(out)
def forced_Q(x):
    m = x % 16
    if m == 7:
        return 'u'
    if m == 11:
        return 't'
    return None
def forced_F(x):
    q = forced_Q(x)
    if q is None:
        return None
    return GENS[q](A(x))
def edge_counts_48(root, w):
    counts = [0]*48
    z = root
    for ch in w:
        old = z % 16
        counts[old*3 + GI[ch]] += 1
        z = GENS[ch](z)
    return counts
def trans16(q, g):
    return GENS[g](q) % 16
def divergence_of(D):
    div = [0]*16
    for q in range(16):
        for g, gi in GI.items():
            c = D[q*3+gi]
            if c != 0:
                div[q] += c
                div[trans16(q, g)] -= c
    return div
BLOCKS = [
    {'id': 'u14', 'phase': 'u', 'k': 14, 'from_zero': 'uuuuputptuutuu', 'x_hex': '0x642fdfb', 'cut': 1},
    {'id': 'u18', 'phase': 'u', 'k': 18, 'from_zero': 'uutuuttuupupuuupup', 'x_hex': '0x6473d46ab', 'cut': 4},
    {'id': 'p12', 'phase': 'p', 'k': 12, 'from_zero': 'putptttttptu', 'x_hex': '0xc84387', 'cut': 0},
    {'id': 'u15', 'phase': 'u', 'k': 15, 'from_zero': 'utututupupuuttt', 'x_hex': '0x191cc387', 'cut': 0},
    {'id': 'p19', 'phase': 'p', 'k': 19, 'from_zero': 'pttutututpttututtuu', 'x_hex': '0x32173ffdfb', 'cut': 1},
    {'id': 'u16', 'phase': 'u', 'k': 16, 'from_zero': 'utttttuttttputut', 'x_hex': '0x6f34fdfb', 'cut': 1},
]
FORBIDDEN = ['uu', 'ttttt', 'ututtu']
def admissible_ok(word):
    for f in FORBIDDEN:
        if f in word:
            return False
    return True
def decompose_circulation(D):
    rem = list(D)
    cycles = []
    guard = 0
    while any(v > 0 for v in rem):
        guard += 1
        if guard > 10000:
            raise RuntimeError('decomp guard')
        start = None
        for q in range(16):
            for g in ['t', 'u', 'p']:
                if rem[q*3+GI[g]] > 0:
                    start = q
                    break
            if start is not None:
                break
        cur = start
        path_v = [cur]
        path_e = []
        pos = {cur: 0}
        while True:
            check_caps()
            nxt_e = None
            for g in ['t', 'u', 'p']:
                if rem[cur*3+GI[g]] > 0:
                    nxt_e = g
                    break
            if nxt_e is None:
                raise RuntimeError('dead end in non-circulation')
            nxt = trans16(cur, nxt_e)
            path_e.append((cur, nxt_e))
            if nxt in pos:
                idx = pos[nxt]
                cyc = path_e[idx:]
                for (q2, g2) in cyc:
                    rem[q2*3+GI[g2]] -= 1
                cycles.append([str(q2) + ':' + g2 for (q2, g2) in cyc])
                break
            pos[nxt] = len(path_v)
            path_v.append(nxt)
            cur = nxt
    return cycles
def run_experiment():
    t0wall = time.time()
    t0cpu = time.process_time()
    blocks_out = []
    diffs = []
    for b in BLOCKS:
        check_caps()
        bid = b['id']; ph = b['phase']; k = b['k']
        fz = b['from_zero']; cut = b['cut']
        x_exp = int(b['x_hex'], 16)
        if len(fz) != k:
            raise RuntimeError('length mismatch ' + bid)
        if fz[0] != ph:
            raise RuntimeError('phase letter mismatch ' + bid)
        root = ROOTS[ph]
        ordinary = fz[1:]
        if len(ordinary) != k-1:
            raise RuntimeError('ordinary length mismatch ' + bid)
        x0, prefs0 = eval_word(root, ordinary)
        if x0 != x_exp:
            raise RuntimeError('endpoint mismatch ' + bid + ' got ' + hex(x0))
        need = cut + 6
        hists = [ordinary]
        states = [x0]
        branches = []
        cur_w = ordinary
        cur_x = x0
        for t in range(need):
            q = forced_Q(cur_x)
            if q is None:
                raise RuntimeError('gate fail ' + bid + ' t=' + str(t))
            branches.append(q)
            h = scanner_H(root, cur_w)
            nxt_w = h + q
            nxt_x, _p = eval_word(root, nxt_w)
            ff = forced_F(cur_x)
            if nxt_x != ff:
                raise RuntimeError('F mismatch ' + bid)
            hists.append(nxt_w)
            states.append(nxt_x)
            cur_w = nxt_w
            cur_x = nxt_x
        motif = ''.join(branches[cut:cut+6])
        if motif != 'ututut':
            raise RuntimeError('motif mismatch ' + bid + ' ' + motif)
        adm_word = ''.join(branches[:cut+6]) + 'u'
        if not admissible_ok(adm_word):
            raise RuntimeError('admissibility fail ' + bid + ' ' + adm_word)
        wi = hists[cut]; wf = hists[cut+6]
        xi = states[cut]; xf = states[cut+6]
        ci = edge_counts_48(root, wi)
        cf = edge_counts_48(root, wf)
        d = [cf[i]-ci[i] for i in range(48)]
        diffs.append(d)
        div_i = divergence_of(ci)
        # path divergence check not needed; store terminals
        blocks_out.append({'id': bid, 'phase': ph, 'k': k, 'from_zero': fz, 'x_hex': b['x_hex'], 'cut': cut, 'ordinary': ordinary, 'branches_all': ''.join(branches), 'motif': motif, 'admissibility_word': adm_word, 'word_initial': wi, 'word_final': wf, 'len_initial': len(wi), 'len_final': len(wf), 'x_initial_hex': hex(xi), 'x_final_hex': hex(xf), 'term_initial_mod16': xi % 16, 'term_final_mod16': xf % 16, 'counts_initial': ci, 'counts_final': cf, 'diff': d, 'states_hex': [hex(s) for s in states]})
    return blocks_out, diffs, t0wall, t0cpu
def search_combinations(diffs):
    n = len(diffs)
    sols = []
    checked = 0
    for coeff in itertools.product(range(5), repeat=n):
        if all(c == 0 for c in coeff):
            continue
        checked += 1
        if checked % 4000 == 0:
            check_caps()
        D = [0]*48
        for j, c in enumerate(coeff):
            if c:
                dj = diffs[j]
                for i in range(48):
                    D[i] += c * dj[i]
        ok = True
        for v in D:
            if v < 0:
                ok = False
                break
        if not ok:
            continue
        if divergence_of(D) != [0]*16:
            continue
        sols.append({'coeff': list(coeff), 'D': list(D)})
    return sols
def file_sha(path):
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        while True:
            b = f.read(65536)
            if not b:
                break
            h.update(b)
    return h.hexdigest()
def git_commit():
    try:
        p = subprocess.run(['git', '-C', '/home/ryan/rule30-lab', 'rev-parse', 'HEAD'], capture_output=True, text=True, timeout=10)
        return p.stdout.strip()
    except Exception:
        return 'unknown'
def main():
    prereg_utc = '2026-09-06T12:00:00Z'
    try:
        with open('/tmp/astra_sixteen_potential.json', 'r') as f:
            old = json.load(f)
            if isinstance(old, dict) and old.get('status') == 'preregistered':
                prereg_utc = old.get('timestamp_utc', prereg_utc)
    except Exception:
        pass
    exp_start_wall = time.time()
    exp_start_cpu = time.process_time()
    blocks_out, diffs, _a, _b = run_experiment()
    sols = search_combinations(diffs)
    cert = None
    cycles = None
    if sols:
        sols.sort(key=lambda s: (sum(s['coeff']), s['coeff']))
        best = sols[0]
        cycles = decompose_circulation(best['D'])
        cert = {'coeff': best['coeff'], 'D': best['D'], 'cycles': cycles}
    wall = time.time() - exp_start_wall
    cpu = time.process_time() - exp_start_cpu
    total_wall = time.time() - START_WALL
    total_cpu = time.process_time() - START_CPU
    ref_hash = file_sha('/home/ryan/rule30-lab/src/python/rule30_research_reference.py')
    self_hash = file_sha('/tmp/astra_sixteen_potential.py')
    with open('/tmp/astra_sixteen_potential.py', 'r') as f:
        self_text = f.read()
    note_paths = ['proofs/informal/problem1_history_potential_obstruction.md', 'proofs/informal/problem1_history_synchronization.md', 'proofs/informal/problem1_zero_cost_return_language.md', 'proofs/informal/problem1_prescribed_history_cost_pullback.md', 'AGENTS.md', 'ASTRA_GOAL.md']
    note_hashes = {}
    for np in note_paths:
        try:
            note_hashes[np] = file_sha('/home/ryan/rule30-lab/' + np)
        except Exception as e:
            note_hashes[np] = 'missing:' + str(e)
    hw = {'platform': platform.platform(), 'processor': platform.processor(), 'cpu_count': os.cpu_count()}
    try:
        with open('/proc/meminfo') as mf:
            hw['meminfo_head'] = mf.read(400)
    except Exception:
        pass
    sw = {'python': sys.version, 'platform': sys.platform}
    try:
        import resource
        sw['maxrss_kb'] = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
    except Exception:
        pass
    diffs_hash = hashlib.sha256(json.dumps(diffs, sort_keys=True).encode()).hexdigest()
    if cert is not None:
        status = 'refuted'
        interpretation = 'Found nonzero nonnegative integer combination coeff 0..4 with componentwise-nonnegative zero-divergence circulation D; by cycle-pumping lemma no bounded-below additive 16-state potential strictly decreases on all six genuine blocks, so universal strict block descent in that class is refuted.'
        proof_scope = 'finite-exhaustive over 5^6-1=15625 coefficient tuples with exact integer arithmetic; all-depth consequence via already-reviewed cycle-pumping lemma.'
    else:
        status = 'inconclusive'
        interpretation = 'No nonzero coeff in 0..4 cube gives a componentwise-nonnegative zero-divergence combination; bounded 15625-case search is inconclusive for the all-depth 16-state class and does not authorize a cap increase or new inputs.'
        proof_scope = 'finite-exhaustive over 5^6-1=15625 tuples only.'
    rec = {'experiment_id': 'astra-sixteen-potential-20260906', 'timestamp_utc': time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()), 'preregistered_utc': prereg_utc, 'git_commit': git_commit(), 'question': 'problem1', 'hypothesis': 'Fixed real additive edge weights omega(r,g) on 16-state scanner graph, bounded below over ALL ordinary histories from both phase roots, strictly decrease across EVERY genuine 3-return block with prescribed H+Q update; tested on six named blocks.', 'backend': 'python-exact-local', 'parameters': {'blocks': [{'id': b['id'], 'phase': b['phase'], 'k': b['k'], 'from_zero': b['from_zero'], 'x_hex': b['x_hex'], 'cut': b['cut']} for b in BLOCKS], 'coeff_range': [0, 4], 'cases': 15625, 'compare': 'cut vs cut+6', 'motif': 'ututut', 'caps': {'cpu_s': 120, 'wall_s': 180, 'mem': '1GiB'}}, 'hardware': hw, 'software': sw, 'runtime_seconds': wall, 'runtime_cpu_seconds': cpu, 'total_wall_seconds': total_wall, 'total_cpu_seconds': total_cpu, 'result_hashes': {'diffs_sha256': diffs_hash, 'self_sha256': self_hash, 'reference_sha256': ref_hash, 'notes': note_hashes}, 'result_summary': {'blocks': blocks_out, 'num_solutions': len(sols), 'certificate': cert, 'all_solution_coeffs': [s['coeff'] for s in sols[:50]]}, 'interpretation': interpretation, 'status': status, 'proof_scope': proof_scope, 'limitations': ['Only six named from-zero words; no new words, frontiers, occurrences, or representations enumerated.', 'Coefficient search bounded to 0..4 (15625 cases) with exact arithmetic; SciPy unavailable and no packages installed.', 'No mutable reference; read-only hash checked.', 'Finite search alone proves no infinite statement; all-depth step uses separately reviewed pumping lemma only if certificate found.', 'Local execution only.'], 'source_text': self_text}
    tmp = '/tmp/astra_sixteen_potential.json.tmp'
    dst = '/tmp/astra_sixteen_potential.json'
    with open(tmp, 'w') as f:
        json.dump(rec, f, indent=2, sort_keys=True)
        f.flush()
        try:
            os.fsync(f.fileno())
        except Exception:
            pass
    os.replace(tmp, dst)
    print('wrote ' + dst + ' status=' + status + ' sols=' + str(len(sols)) + ' wall=' + str(round(wall, 3)))
    if cert is not None:
        print('coeff=' + str(cert['coeff']))
        print('D nonzero entries=' + str([(i, v) for i, v in enumerate(cert['D']) if v != 0]))
        print('cycles=' + str(len(cycles)))
    else:
        for bo in blocks_out:
            print(bo['id'] + ' term ' + str(bo['term_initial_mod16']) + '->' + str(bo['term_final_mod16']) + ' diff_nonzero=' + str([(i, v) for i, v in enumerate(bo['diff']) if v != 0][:12]))
if __name__ == '__main__':
    main()

